use std::collections::BinaryHeap;

/// Calculates the median of a given array.
///
/// # Examples
/// ```
/// let arr = vec![3, 1, 2, 4, 5];
/// let median = calculate_median(&arr);
/// assert_eq!(median, 3);
/// ```
fn calculate_median(arr: &Vec<i32>) -> i32 {
    let mut heap = BinaryHeap::from(arr);
    let mut count = 0;

    // Push all elements into the heap
    while let Some(&value) = heap.pop() {
        count += 1;
    }

    // If the count is odd, return the middle element
    if count % 2 == 1 {
        return value;
    }

    // If the count is even, return the average of the two middle elements
    let half_count = count / 2;
    let middle1 = heap.pop().unwrap();
    let middle2 = heap.pop().unwrap();
    (middle1 + middle2) / 2.0

