program LargestPrimeFinder;

{$APPTYPE CONSOLE}

uses
  SysUtils;

function IsPrime(n: Integer): Boolean;
var
  i: Integer;
begin
  if n <= 1 then
    Result := False
  else
    Result := True;
  for i := 2 to n-1 do
    if n mod i = 0 then
      Result := False;
  Result;
end;

function FindLargestPrimeBelow(n: Integer): Integer;
var
  i: Integer;
begin
  Result := 2;
  while i < n do
    if IsPrime(i) then
      Inc(Result);
    Inc(i);
end;

begin
  Writeln('Enter a number: ');
  Result := FindLargestPrimeBelow(Readln);
  Writeln('The largest prime number less than ' + IntToStr(Result) + ' is: ' + IntToStr(Result));
  Readln;
end.
