// Importing necessary packages
import { strict as assert } from 'assert';

/**
 * Reverses every other character in a given string.
 * 
 * @param inputString The string to be processed.
 * @returns The processed string with every other character reversed.
 */
function reverseEveryOtherChar(inputString: string): string {
    let reversedString = '';
    for (let i = 0; i < inputString.length; i += 2) {
        reversedString += inputString[i].charCodeAt(0).toString().toUpperCase();
    }
    return reversedString;
}

