```swift
import Foundation

// Function to count occurrences of a character in a text file
func countOccurrencesOfCharacter(filePath: String, character: Character) -> Int {
    var count = 0
    let fileHandle = FileHandle(file: URL(fileURLWithPath: filePath), mode: .read, attributes: nil)

    // Open the file in read mode
    fileHandle.open(forReading: .init(), options: [])

    // Read the file line by line
    for line in fileHandle.readLines(atMost: 1000) {
        let line = String(line)
        // Count occurrences of the character
        count += line.count { $0 == character }
    }

    // Close the file handle
    fileHandle.close()

    return count
}

