#include <iostream>
#include <string>
#include <sstream>
#include <cassert>

// Function to convert a binary number to a decimal number
int binaryToDecimal(const std::string& binary) {
    // Base case: if the binary string is empty, return 0
    if (binary.empty()) {
        return 0;
    }
    // Recursive case: convert the first bit and add to the result of the rest
    return binary[0] - '0' * 2 + binaryToDecimal(binary.substr(1));
}

